/** Owned HTTPS test fixture. Synthetic identity/state ONLY; never product runtime. */
import {createServer} from 'node:https';import {readFile} from 'node:fs/promises';import {randomUUID} from 'node:crypto';
import {createSupportWorkflowHttpHandler} from '../../../src/http/support-workflow.ts';import {decideSupportTransition,type SupportTicket} from '../../../src/domain/support-workflow.ts';import {eventDto} from '../../../src/http/serialization.ts';import type {Principal,TicketEvent} from '../../../src/domain/model.ts';
if(process.env.HELPDESK_OWNED_WORKFLOW_BROWSER!=='synthetic-loopback')throw Error('Owned fixture authorization required');
const id=(n:number)=>'10000000-0000-4000-8000-'+String(n).padStart(12,'0');const p:Principal={id:id(1),workspaceId:id(2),kind:'human',workspaceRole:null,grants:[{accountId:id(3),role:'agent'}],scopes:['tickets:read','tickets:write']};const customer:Principal={...p,grants:[{accountId:id(3),role:'requester'}]};
const original:SupportTicket={id:id(4),workspaceId:p.workspaceId,accountId:id(3),productInstanceId:id(6),serviceCode:'SUPPORT',createdBy:p.id,assignedTo:p.id,subject:'Synthetic',description:'Synthetic',priority:'normal',version:2,status:'open',coverageId:id(7),contractVersionId:id(8),contractSnapshot:{contractId:id(9),version:1,policy:{}},createdAt:'2026-10-13T12:00:00.000000Z',updatedAt:'2026-10-13T12:00:00.000000Z',lastEventAt:'2026-10-13T12:00:00.000000Z',profileVersionId:'P1',closedAt:null,resolution:null,approval:'not_required'};
let ticket=structuredClone(original),enabled=true,events:TicketEvent[]=[],receipts=new Map<string,{command:string;result:any}>(),origin='',handler:ReturnType<typeof createSupportWorkflowHttpHandler>;
const page=`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Fixture M06</title><style>body{font:16px system-ui;max-width:700px;margin:24px;padding:8px}textarea{box-sizing:border-box;width:100%;height:100px}button{padding:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Fixture M06 — identidade e estado sintéticos</h1><label>Devolutiva pública<textarea id="body">Envie a planilha.</textarea></label><button id="send">Confirmar devolutiva</button><p role="status" id="status"></p><pre id="timeline"></pre><script>const key='m06-browser-intent-001';document.querySelector('#send').onclick=async()=>{const r=await fetch('/v1/tickets/${id(4)}/workflow-commands',{method:'POST',headers:{'Content-Type':'application/json','If-Match':'"2"','Idempotency-Key':key},body:JSON.stringify({action:'request_customer',body:document.querySelector('#body').value})});const v=await r.json();document.querySelector('#status').textContent=r.ok?'Confirmado: '+v.version+(v.replayed?' (replay)':''):'Recusado: '+v.code;const timeline=await fetch('/_test/timeline');document.querySelector('#timeline').textContent=JSON.stringify(await timeline.json(),null,2);};</script></html>`;
const server=createServer({cert:await readFile(process.env.HELPDESK_WORKFLOW_TEST_CERT!),key:await readFile(process.env.HELPDESK_WORKFLOW_TEST_KEY!)},async(req,res)=>{try{const url=new URL(req.url!,origin);if(url.pathname==='/'){res.setHeader('content-type','text/html; charset=utf-8');res.end(page);return;}
 if(url.pathname==='/_test/reset'){ticket=structuredClone(original);events=[];receipts=new Map();enabled=true;res.end('{}');return;}
 if(url.pathname==='/_test/close'){enabled=false;res.end('{}');return;}
 if(url.pathname==='/_test/counts'){res.setHeader('content-type','application/json');res.end(JSON.stringify({writes:events.length}));return;}
 if(url.pathname==='/_test/timeline'){res.setHeader('content-type','application/json');res.end(JSON.stringify(events.map(e=>eventDto(customer,e))));return;}
 const chunks:Buffer[]=[];let size=0;for await(const chunk of req){size+=chunk.length;if(size>100000)throw Error('Bounded fixture body');chunks.push(chunk);}
 const request=new Request(url,{method:req.method,headers:req.headers as Record<string,string>,...(req.method==='GET'?{}:{body:Buffer.concat(chunks)})}),response=await handler(request);res.writeHead(response.status,Object.fromEntries(response.headers));res.end(Buffer.from(await response.arrayBuffer()));
 }catch{res.writeHead(500);res.end('Owned fixture unavailable');}});
await new Promise<void>(resolve=>server.listen(0,'127.0.0.1',resolve));const address=server.address();if(!address||typeof address==='string')throw Error('Owned address required');origin='https://127.0.0.1:'+address.port;
handler=createSupportWorkflowHttpHandler({enabled:()=>enabled,origin,authenticate:async()=>p,rateLimiter:{beforeAuthentication:async()=>{},afterAuthentication:async()=>{}},directory:{readTicketResources:async()=>[{connectionId:id(10),tenantId:'T',type:'work',id:'A'}]},service:{async execute(actor,target,_refs,command,key,_request,_signal,admission){admission?.();const raw=JSON.stringify(command),prior=receipts.get(key);if(prior){if(prior.command!==raw)throw Object.assign(Error(),{code:'workflow_idempotency_conflict'});return {...prior.result,replayed:true};}const at=new Date().toISOString(),decision=decideSupportTransition(actor,ticket,{versionId:'P1',status:'published',reopenWindowMicros:'604800000000'},command,at),eventId=randomUUID();ticket=decision.after;events.push({id:eventId,workspaceId:p.workspaceId,accountId:ticket.accountId,ticketId:target,actorId:p.id,type:'ticket.status_changed',customerVisible:true,createdAt:at,data:{to:ticket.status,reason:'PRIVATE_SYNTHETIC_REASON',public_interaction:{action:'request_customer',body:decision.event.body,version:ticket.version}}});const result={ticketId:target,workspaceId:p.workspaceId,accountId:ticket.accountId,actorId:p.id,profileVersionId:'P1',version:ticket.version,status:ticket.status,eventId,replayed:false};receipts.set(key,{command:raw,result});return result;}}});
console.log(JSON.stringify({url:origin}));
